// or the token `claude setup-token` mints from a subscription. A secret the repository does not
// have arrives as an empty string, which is dropped so the agent never sees a blank credential.
const NATIVE_NAMES = ['ANTHROPIC_API_KEY', 'CLAUDE_CODE_OAUTH_TOKEN'];
for (const name of NATIVE_NAMES) if (!process.env[name]) delete process.env[name];
