  'PATH', 'HOME', 'USER', 'LOGNAME', 'SHELL',
  // where temporary files go, and what kind of terminal this is
  'TMPDIR', 'TEMP', 'TMP', 'TERM',
  // how text is encoded, what the clock says, and that this is CI — a test runner that opens a watch prompt hangs an attempt
  'LANG', 'LC_ALL', 'LC_CTYPE', 'TZ', 'CI',
