  'NODE_OPTIONS', 'NVM_DIR', 'PNPM_HOME', 'COREPACK_HOME',
  // the JVM and Android toolchains an Expo or Gradle build needs
  'JAVA_HOME', 'ANDROID_HOME', 'ANDROID_SDK_ROOT', 'GRADLE_USER_HOME',
  // the Elixir toolchain
  'MIX_HOME', 'HEX_HOME',
