const theMap = buildTheMap();

// A machine with no graft on it — or one whose map would not build — hands over exactly the words
// it handed over yesterday: the stored instruction and the starting point, and not one byte more.
const theInstruction = [run.instruction, startingPoint, ...(theMap ? [theMap] : [])].join('\n\n');

// The two names that are not the agent's to move: the default branch, and the branch it was
// started from -- an earlier attempt's, already judged or waiting to be.
const notTheAgentsBranch = [theDefault, baseBranch];
