// will ever see. Trust is recorded the way the CLI itself records it, so the log stays clean and
// nobody reads a cosmetic warning as the agent being blocked (someone did, on the second real run).
try {
  const p = `${process.env.HOME}/.claude.json`;
  const cfg = existsSync(p) ? JSON.parse(readFileSync(p, 'utf8')) : {};
  cfg.projects = { ...(cfg.projects ?? {}), [process.cwd()]: { ...(cfg.projects?.[process.cwd()] ?? {}), hasTrustDialogAccepted: true } };
  writeFileSync(p, JSON.stringify(cfg));
} catch { /* a warning in the log, nothing more */ }

// ── the runner's hands: a push and a press the agent can ask for. ──
//
// Since Constat № 33 the judged agent's environment holds no GitHub credential, and that is not
// going back: a witness's credential in the examined party's pocket makes every pulled row a
// claim. But the discipline the whole product rests on — push the check RED, before the code that
// makes it green — needs a push while the implementation does not exist yet, and the runner only
// pushed once, after the agent had ended. So every attempt's red rung was dark: not because the
// agent skipped it, but because nobody could push a failing check while it was still failing.
//
// The runner keeps the token, and lends the ACT. Two commands are written onto the agent's PATH
// for the length of this attempt — constat-push and constat-pull-request — and each is four lines
// that ask THIS process, over a loopback socket, to do the thing with its own credential. Nothing
// is added to the agent's environment but a directory on PATH: no token, no address of Constat,
// no OIDC variable. A hand, not a key.
//
// Capped, because a hand is not a blank cheque: a fixed number of pushes per attempt and one
// pull request, and past that the runner says so in words the agent can read. And every act is
// reported to Constat while the run is still running, with both halves on it — the runner's own
// act, at the agent's request — so the record never credits a push to the party that could not
// have made it, and never hides who asked for it.
const HAND_PUSHES = 20;
const HAND_PULL_REQUEST_TRIES = 3;
