let openedPullRequest = null;
// One at a time: two shims answered at once would run two git pushes in the same checkout.
let handQueue = Promise.resolve();

/** Say what this runner did with its own hands, on the run, while the run is still running. */
async function tellConstat(act, fields) {
  try { await constat('POST', `/runner/runs/${run.id}/acts`, { act, ...fields }); }
  catch (err) { console.error(`::warning::could not tell Constat about the ${act} it made on the agent's request: ${err.message}`); }
}

async function lendPush() {
  const branch = git('rev-parse', '--abbrev-ref', 'HEAD');
  if (notTheAgentsBranch.includes(branch)) return [409, `You are still on ${branch}. Make your own branch first — the runner pushes the branch you are on, and never the default branch nor the one you were started from.`];
  if (handsLent.push >= HAND_PUSHES) {
    return [429, `The runner has already pushed ${handsLent.push} times for this attempt, which is all it lends per attempt. Keep committing: whatever is committed when you end is pushed once more.`];
  }
  handsLent.push += 1;
  try { git('push', '--set-upstream', 'origin', branch); }
  catch (err) {
    const why = `${err.message}\n${err.stderr ?? ''}`.split('\n').map((l) => l.trim()).find((l) => l !== '') ?? 'no reason given';
    await tellConstat('push', { branch, refused: why });
    return [502, `git refused the push: ${why}`];
  }
  const sha = git('rev-parse', 'HEAD');
  console.log(`Pushed ${branch} at ${sha.slice(0, 7)} — the runner's own act, at the agent's request.`);
  await tellConstat('push', { branch, commitSha: sha });
  const ci = await pressCiOn(branch, sha);
  if (ci.dispatched.length > 0) await tellConstat('ci_pressed', { branch, commitSha: sha, workflows: ci.dispatched });
  for (const why of ci.refused) await tellConstat('ci_pressed', { branch, commitSha: sha, refused: why });
  const said = ci.dispatched.length > 0
    ? `CI is running on it: ${ci.dispatched.join(', ')}.`
    : ci.refused.length > 0 ? `CI could not be started: ${ci.refused.join('; ')}`
    : 'No workflow here declares workflow_dispatch, so no CI run was started.';
  return [200, `Pushed ${branch} at ${sha.slice(0, 7)}. ${said}`];
}

async function lendPullRequest(title, body) {
  const branch = git('rev-parse', '--abbrev-ref', 'HEAD');
  if (notTheAgentsBranch.includes(branch)) return [409, `You are still on ${branch}. Make your own branch and commit first.`];
  // One attempt opens one pull request. Asked again, the runner hands back the same one rather
  // than opening a second against the same branch.
  if (openedPullRequest) return [200, `The pull request is already open, and one attempt opens one: ${openedPullRequest}`];
  if (handsLent.pull_request >= HAND_PULL_REQUEST_TRIES) return [429, 'The runner has tried to open the pull request as often as it will for one attempt. Carry on with your work; the branch is pushed either way.'];
  handsLent.pull_request += 1;
  try { git('push', '--set-upstream', 'origin', branch); } catch { /* it may be pushed already; the open below says so if not */ }
  const heading = typeof title === 'string' && title.trim() !== '' ? title.trim() : `Constat attempt on ${branch}`;
  const words = (typeof body === 'string' && body.trim() !== '' ? body.trim() + '\n\n' : '')
    + 'Opened by the Constat runner with its own credential, at the judged agent\'s request: the agent holds no GitHub credential of its own.';
  const opened = await openPullRequest(branch, heading, words);
  if (opened.error) {
    await tellConstat('pull_request', { branch, refused: opened.error });
    return [502, `The pull request could not be opened: ${opened.error}. Carry on — your commits are pushed, and this is on the record as the runner's refusal, not yours.`];
  }
  openedPullRequest = opened.url;
  console.log(`Opened ${openedPullRequest} — the runner's own act, at the agent's request.`);
  await tellConstat('pull_request', { branch, pullRequestUrl: openedPullRequest });
  return [200, `Opened the pull request: ${openedPullRequest}`];
}

/** `gh` where the machine has it, GitHub's REST API with the job's own token where it does not. */
async function openPullRequest(branch, title, body) {
  if (haveGh()) {
    try {
      const url = execFileSync('gh', ['pr', 'create', '--base', theDefault, '--head', branch, '--title', title, '--body', body], { encoding: 'utf8' }).trim();
      return { url: url.split('\n').filter((l) => l.startsWith('http')).pop() ?? url };
    } catch (err) { return { error: `${String(err.message).slice(0, 200)} ${String(err.stderr ?? '').slice(0, 200)}`.trim() }; }
  }
  const made = await github('POST', '/pulls', { title, head: branch, base: theDefault, body });
  if (made.ok) return { url: made.json?.html_url ?? null };
  // Already open is not a refusal: the runner hands back the one that exists.
  const existing = await github('GET', `/pulls?head=${encodeURIComponent((process.env.GITHUB_REPOSITORY || '').split('/')[0] + ':' + branch)}&state=open`);
  const found = existing.ok && Array.isArray(existing.json) ? existing.json[0]?.html_url ?? null : null;
  return found ? { url: found } : { error: made.error };
}

const handDir = mkdtempSync(join(tmpdir(), 'constat-hand-'));
const handSecret = randomBytes(24).toString('hex');
// A dir of its own with no package.json above it inherits Node's default; saying it here means the
// shims below are read the same way wherever TMPDIR happens to sit.
writeFileSync(join(handDir, 'package.json'), '{"type":"commonjs"}');
const handServer = createServer((req, res) => {
  let raw = '';
  req.on('data', (c) => { raw += String(c); });
  req.on('end', () => {
    const answer = (status, said) => { res.statusCode = status; res.setHeader('content-type', 'application/json'); res.end(JSON.stringify({ said })); };
    // The secret is written into the shims, not into the agent's environment: another job on the
    // same machine cannot ask this runner to push someone else's branch.
    if (req.headers['x-constat-hand'] !== handSecret) return answer(403, 'That is not this attempt’s hand.');
    let asked = {}; try { asked = JSON.parse(raw || '{}'); } catch { /* said below */ }
    handQueue = handQueue
      .then(() => (asked.act === 'push' ? lendPush()
        : asked.act === 'pull_request' ? lendPullRequest(asked.title, asked.body)
        : [400, 'The runner lends two hands: constat-push and constat-pull-request.']))
      .then(([status, said]) => answer(status, said))
      .catch((err) => answer(500, `The runner could not: ${err.message}`));
  });
});
await new Promise((resolve) => handServer.listen(0, '127.0.0.1', resolve));
handServer.unref();
const handPort = handServer.address().port;
const handShim = (act) => `#!/usr/bin/env node
// Written by the Constat runner for THIS attempt, and thrown away with it. It holds no credential:
// it asks the runner's own process — which holds the token — to do the act and prints what it says.
const http = require('node:http');
const args = process.argv.slice(2);
const value = (name) => { const i = args.indexOf('--' + name); return i >= 0 ? args[i + 1] : null; };
const payload = JSON.stringify({ act: '${act}', title: value('title'), body: value('body') });
const req = http.request({
  host: '127.0.0.1', port: ${handPort}, path: '/hand', method: 'POST',
  headers: { 'content-type': 'application/json', 'content-length': Buffer.byteLength(payload), 'x-constat-hand': '${handSecret}' },
}, (res) => {
  let raw = '';
  res.on('data', (d) => { raw += d; });
  res.on('end', () => {
    let said = raw;
    try { said = JSON.parse(raw).said ?? raw; } catch (e) { /* whatever it said */ }
    process.stdout.write(said + '\\n');
    process.exit(res.statusCode === 200 ? 0 : 1);
  });
});
req.setTimeout(600000, () => { req.destroy(new Error('the runner did not answer within ten minutes')); });
req.on('error', (err) => { process.stderr.write('the runner did not answer: ' + err.message + '\\n'); process.exit(1); });
req.end(payload);
`;
for (const [name, act] of [['constat-push', 'push'], ['constat-pull-request', 'pull_request']]) {
  writeFileSync(join(handDir, name), handShim(act));
  chmodSync(join(handDir, name), 0o755);
}
// The one thing the hand adds to the agent's environment: a directory on PATH.
agentEnv.PATH = `${handDir}${agentEnv.PATH ? `:${agentEnv.PATH}` : ''}`;
console.log('The runner\'s hands are on the agent\'s PATH: constat-push and constat-pull-request.');

// ── run the agent, with the caps enforced HERE, on the machine that is spending. ──
const startedAt = Date.now();
const runtimeMs = run.envelope.runtime_minutes * 60_000;
child = spawn('claude', [
  '-p', '--output-format', 'stream-json', '--verbose',
  '--model', run.model,
  '--max-budget-usd', String(run.envelope.budget_usd),
  '--permission-mode', 'bypassPermissions',
  '--dangerously-skip-permissions',
  theInstruction,
], { stdio: ['ignore', 'pipe', 'inherit'], env: agentEnv });

// The agent's stream, one JSON object per line: tool uses are echoed so a person watching the job
// sees the work move — a silent log reads as a blocked agent — and the final `result` line carries
// what the CLI says about its own run.
let result = null; let pending = '';
const hint = (input) => input?.file_path ?? input?.path ?? input?.command ?? input?.pattern ?? input?.description ?? '';
child.stdout.on('data', (d) => {
  pending += d;
  const lines = pending.split('\n'); pending = lines.pop() ?? '';
  for (const line of lines) {
    let msg; try { msg = JSON.parse(line); } catch { continue; }
    if (msg.type === 'result') result = msg;
    if (msg.type === 'assistant') {
      for (const block of msg.message?.content ?? []) {
        if (block.type === 'tool_use') console.log(`  → ${block.name} ${String(hint(block.input)).slice(0, 120)}`);
      }
    }
  }
});
let haltReason = null;
const finished = new Promise((resolve) => child.on('close', (code) => resolve(code)));

// The stop channel's reader: the owner presses Stop in Constat, this asks every 30 s, and honours
// it by ending the agent. Both halves of that fact are then on the record — theirs and ours.
const watcher = (async () => {
  while (child.exitCode === null) {
    if (Date.now() - startedAt > runtimeMs) { haltReason = 'runtime'; child.kill('SIGTERM'); return; }
    try {
      const { stop } = await constat('GET', `/runner/runs/${run.id}/stop`);
      if (stop) { haltReason = 'owner_stop'; child.kill('SIGTERM'); return; }
    } catch { /* a failed read is not a stop; asked again next tick */ }
    await sleep(STOP_POLL_MS);
  }
})();
const exitCode = await finished;
await watcher.catch(() => {});
// The hands are lent for the length of the attempt, and the attempt is over: nothing else can ask
// this runner to push anything from here on.
handServer.close();

// ── what the CLI said about its own run: cost and usage are the provider's own figures. ──
if (!result && pending.trim()) { try { const last = JSON.parse(pending); if (last.type === 'result') result = last; } catch { /* no result line */ } }
const usage = result?.usage ?? {};
const inputTokens = ['input_tokens', 'cache_creation_input_tokens', 'cache_read_input_tokens']
  .map((k) => usage[k]).filter((v) => typeof v === 'number').reduce((a, b) => a + b, 0) || null;
// A cap crossed AFTER the work was finished is not a halt. On 4 September 2026 (finding 16, 17:06)
// an agent committed, wrote its report, and then spent eight cents more; the run was labelled
// halted, the requirement fell back to approved, and a finished report was thrown away. Two facts
// tell "finished, then overspent" from "stopped mid-work": commits beyond the base, and a report
// file on disk. With both, the work is there to be judged — so the outcome is `completed`, and the
// overrun is said in words instead of being the reason for discarding it. Without either — no
// commit, or no report — the cap really did stop the work, and halted stays.
const crossedCap = result?.subtype === 'error_max_budget_usd' || result?.subtype === 'error_max_turns';
let commitsBeyondBase = 0;
try { commitsBeyondBase = Number(git('rev-list', '--count', `${startedAtCommit}..HEAD`)) || 0; } catch { commitsBeyondBase = 0; }
const finishedFirst = crossedCap && commitsBeyondBase > 0 && existsSync(REPORT_PATH);
const spent = typeof result?.total_cost_usd === 'number' ? result.total_cost_usd : null;
const overBy = spent === null ? null : spent - run.envelope.budget_usd;
const overrunNote = overBy !== null && overBy > 0
  ? `finished, then crossed the cap by $${overBy.toFixed(2)} — its last commit and its report were already in place.`
  : `finished, then crossed the cap (${result?.subtype === 'error_max_turns' ? 'the turn limit' : 'the budget'}) — its last commit and its report were already in place.`;
if (!haltReason && crossedCap && !finishedFirst) haltReason = result?.subtype === 'error_max_budget_usd' ? 'budget' : 'max_turns';

// ── the agent's last words, for a run that ends with nothing to push. ──
// On 5 September 2026 at 18:51 an attempt read files for nine minutes, spent $3.23 and committed
// nothing. The record said it failed because "agent run ended: success" — the subtype of the CLI's
// result line, and nothing else. The exit code was 1 and the result line said is_error, and the
// agent's own last words were thrown away, so a usage limit, a refusal, and a connection cut off
// mid-turn all read the same. When there is no branch to push there is nothing else to look at, so
// everything the CLI said about its own ending is written on the run, as one sentence.
const firstLines = (text, howMany = 5, atMost = 600) => String(text)
  .split('\n').map((l) => l.trim()).filter((l) => l !== '')
  .slice(0, howMany).join(' ').slice(0, atMost);
const agentsLastWords = typeof result?.result === 'string' && result.result.trim() !== ''
  ? firstLines(result.result) : null;
const endedWithNothingToPush = () => {
  const cli = result
    ? `the CLI called it ${result.subtype ?? 'unknown'} (is_error: ${result.is_error ?? 'not said'})`
    : 'the CLI printed no result line';
  return `the agent ended with exit code ${exitCode} and no commit; ${cli}; `
    + (agentsLastWords ? `its last words: ${agentsLastWords}` : 'it left no last words');
};

// ── the agent's report: a CLAIM, forwarded whole. Constat parses it and records it as claims. ──
const report = existsSync(REPORT_PATH) ? JSON.parse(readFileSync(REPORT_PATH, 'utf8')) : null;

// Push whatever the agent committed, so CI can run on it and Constat can witness it. The branch
// name is the one the instruction assigned; if the agent never created it, there is nothing to push.
let branch = null; let commitSha = null; let prUrl = openedPullRequest ?? report?.pr_url ?? null;
try {
  branch = git('rev-parse', '--abbrev-ref', 'HEAD');
  // Neither the default branch nor the branch this attempt was STARTED from: the second is an
  // earlier attempt's, already judged or waiting to be, and pushing this attempt's work onto it
  // would rewrite the record of somebody else's.
  if (notTheAgentsBranch.includes(branch)) branch = null;
  else { git('push', '--set-upstream', 'origin', branch); commitSha = git('rev-parse', 'HEAD'); }
} catch (err) { console.error(`::warning::could not push the branch: ${err.message}`); }

// CI on the agent's branch, one last time — for whatever the agent committed and did not ask to
// have pushed. Never the release workflow: it deploys, and a branch is not released until a person
// has judged it and pressed Release. On 3 September 2026 this loop pressed constat-release on an
// attempt's branch and deployed unjudged code six minutes before its verdict.
//
// Once per head commit: the agent's own asking (constat-push) already pressed CI on every commit
// it pushed, and pressing again on the same commit only adds a duplicate run for Constat to
// choose between.
if (branch) await pressCiOn(branch, commitSha);

const outcome = haltReason ? 'halted' : (finishedFirst || (exitCode === 0 && result?.subtype === 'success')) ? 'completed' : 'failed';
await constat('POST', `/runner/runs/${run.id}/finished`, {
  outcome, haltReason, branch, commitSha, prUrl, baseBranch, baseCommit,
  startedFromRunId, startingPointNote,
  inputTokens, outputTokens: usage.output_tokens ?? null,
  estimatedCost: typeof result?.total_cost_usd === 'number' ? result.total_cost_usd : null,
  // A failed attempt WITH a branch has the branch, the diff and CI to be read; one without has
  // only what the CLI said, so that is what is written down.
  error: finishedFirst ? overrunNote
    : outcome !== 'failed' ? null
    : branch === null ? endedWithNothingToPush()
    : result?.subtype ? `agent run ended: ${result.subtype}` : `exit code ${exitCode}`,
  report,
});
reported = true;
console.log(`Reported ${outcome} for attempt ${run.id}. Constat will witness the branch on its next look.`);
